<?php session_start();if(isset($_SESSION['loggedin'])&&$_SESSION['loggedin']===true){if(!isset($_GET['id'])||empty($_GET['id'])){header("Location: ../allposts-not-inuse");exit;}require_once '../credentials.php';$conn=new mysqli($dbHost,$dbUsername,$dbPassword,$dbName);if($conn->connect_error){die("Connection failed: ".$conn->connect_error);}$title=$description="";$editMessage="";if($_SERVER["REQUEST_METHOD"]=="POST"){$title=$_POST['title'];$description=$_POST['description'];$stmt=$conn->prepare("UPDATE blog_posts SET title = ?, description = ? WHERE id = ?");$stmt->bind_param("ssi",$title,$description,$_GET['id']);if($stmt->execute()){$editMessage="Post modified successfully. Redirecting to All Posts Page . . .";echo '<script>';echo 'setTimeout(function() { window.location.href = "./allposts-not-inuse.php"; }, 3000);';echo '</script>';}else{$editMessage="Failed to modify post.";}$stmt->close();}$stmt=$conn->prepare("SELECT title, description FROM blog_posts WHERE id = ?");$stmt->bind_param("i",$_GET['id']);$stmt->execute();$stmt->bind_result($title,$description);$stmt->fetch();$stmt->close();$conn->close();}else{header("Location: /login.php");exit();} ?><?php include '../Header.php'; ?><div class="ttm-page-title-row"><div class="ttm-bg-layer ttm-page-title-row-bg-layer"></div><div class="container"><div class="row"><div class="text-center col-md-12"><div class="ttm-textcolor-white title-box"><div class="ttm-textcolor-white page-title-heading"><h1 class="title">Edit Post</h1></div><div class="breadcrumb-wrapper"><span><a href="/"title="Homepage"><i class="ti ti-home"></i> Home </a></span><span class="ttm-bread-sep">: : </span><span><span class="ttm-textcolor-skincolor">Blog Post</span></span> <span class="ttm-bread-sep">: : </span><span><span class="ttm-textcolor-skincolor">Edit Post</span></span></div></div></div></div></div></div><section class="error-404"><header class="text-center section-title"><h5>Edit Post</h5></header><div class="container pb-4"><div class="row"><div class="col-md-12"><div class="text-center row-title style4"><section><div class="container"><?php if(!empty($editMessage)): ?><div class="alert alert-success"><?php echo $editMessage; ?></div><?php endif; ?><form action="<?php echo "editpost".'?id='.$_GET['id']; ?>"method="POST"><div class="form-group"><label for="title">Title:</label> <input class="form-control"name="title"value="<?php echo $title; ?>"id="title"required></div><div class="form-group"><label for="description">Description:</label> <textarea class="form-control"id="description"name="description"required style="height:300px"><?php echo $description; ?></textarea></div><div class="form-group"><input class="mb-20 mt-30 ttm-btn ttm-btn-bgcolor-black ttm-btn-shape-round ttm-btn-size-md ttm-btn-style-fill"name="submit"value="Update"type="submit"></div></form></div></section></div><a href="./allposts-not-inuse"class="mb-20 mt-30 ttm-btn ttm-btn-bgcolor-black ttm-btn-shape-round ttm-btn-size-md ttm-btn-style-fill">Add New Post</a></div></div></div></section><?php include '../footer.php'; ?>